<script setup lang="ts">
type Profile={id:string;displayName:string;revision:number;joinedAt:string;emailMethod:null|{email:string;assurance:string};providers:{provider:string;email:string|null;emailClaimVerified:boolean}[];sessions:{id:string;transport:string;method:string;lastActiveAt:string;expiresAt:string}[]};
const member=useMember(),profile=ref<Profile>(),name=ref(''),error=ref(''),busy=ref(false),loaded=ref(false);
const confirmation=ref(''),exportText=ref('');
async function exportData(){try{exportText.value=JSON.stringify((await $fetch<{data:unknown}>('/api/v1/me/export')).data,null,2);}catch{error.value='Your export could not be loaded. Retry without changing your account.';}}
async function clearHistory(){try{const detail={pending:[] as Promise<void>[]};window.dispatchEvent(new CustomEvent('aggregator:history-clear-request',{detail}));await Promise.all(detail.pending);await member.mutate('/api/v1/me/progress','DELETE',{});window.dispatchEvent(new Event('aggregator:clear-history'));error.value='Listening history cleared.';}catch(e){error.value=memberError(e);}}
async function accountAction(action:'revoke-other'|'delete-account'){
 if(busy.value)return;busy.value=true;error.value='';
 try{await member.mutate('/api/v1/me/account-action','POST',{action,confirmation:action==='delete-account'?confirmation.value:'REVOKE OTHER SESSIONS'});
 if(action==='delete-account'){member.session.value=null;profile.value=undefined;exportText.value='';window.dispatchEvent(new Event('account-logout'));clearNuxtData();await navigateTo('/');}else await load();
 }catch(e){error.value=(e as {statusCode?:number}).statusCode===403?'Sign in again to the same account, then retry within 15 minutes. Your account is unchanged.':memberError(e);}finally{busy.value=false;}
}
async function load(){try{await member.refresh();if(!member.session.value)return;profile.value=(await $fetch<{data:Profile}>('/api/v1/me/profile')).data;name.value=profile.value.displayName;}catch{error.value='Profile could not be loaded. Your saved data is unchanged.';}finally{loaded.value=true;}}
async function save(){if(!profile.value||busy.value)return;busy.value=true;error.value='';try{profile.value=(await member.mutate<{data:Profile}>('/api/v1/me/profile','PATCH',{revision:profile.value.revision,displayName:name.value})).data;await member.refresh();}catch(e){error.value=memberError(e)+' Your draft name is retained.';}finally{busy.value=false;}}
onMounted(load);useHead({title:'Profile — The Aggregator'});
</script>
<template><MemberFrame><h1>Your Profile</h1><p v-if="!loaded" role="status">Loading your account…</p><p v-else-if="!member.session.value"><NuxtLink to="/sign-in?returnTo=/profile">Sign in to view your Profile</NuxtLink></p><template v-if="profile"><span class="profile-initial" aria-label="Your local initial">{{ Array.from(profile.displayName||'Reader')[0]?.toLocaleUpperCase() }}</span><form class="member-form" @submit.prevent="save"><label>Display name<input v-model="name" class="field-input" maxlength="80" required autocomplete="nickname"></label><button class="control control--primary" :disabled="busy">{{ busy?'Saving…':'Save account details' }}</button></form><section class="member-card"><h2>Connected sign-in methods</h2><p v-for="provider in profile.providers" :key="provider.provider">Google · {{ provider.email||'Email not supplied' }} · {{ provider.emailClaimVerified?'Google-verified email claim':'Email claim unverified' }}</p><p v-if="profile.emailMethod">{{ profile.emailMethod.email }} · {{ profile.emailMethod.assurance }}</p><p>Local captured-mail ownership cannot be used to link a real Google account.</p></section><section class="member-card"><h2>Interests and preferences</h2><div class="member-actions"><NuxtLink class="control" to="/interests">Edit your interests</NuxtLink><NuxtLink class="control" to="/preferences">Reading, media and privacy preferences</NuxtLink></div></section><section class="member-card"><h2>Active sessions</h2><ul><li v-for="session in profile.sessions" :key="session.id">{{ session.transport }} · {{ session.method }} · Last active {{ new Date(session.lastActiveAt).toLocaleString() }}</li></ul><button class="control" @click="member.logout">Sign out of this session</button></section><section class="member-card"><h2>Privacy and account controls</h2><p>Your interests and saved data are private. These actions affect The Aggregator only, not your Google account. Sensitive actions require sign-in within the last 15 minutes.</p><div class="member-actions"><button class="control" :disabled="busy" @click="accountAction('revoke-other')">Revoke other Aggregator sessions</button><button class="control" @click="clearHistory">Clear listening history</button><button class="control" @click="exportData">Read my data export</button></div><details v-if="exportText"><summary>Your private export (selectable JSON)</summary><pre class="profile-export">{{ exportText }}</pre></details><details><summary>Delete my Aggregator account</summary><p>Removes sign-in links, preferences, interests, bookmarks, queue and history; invalidates all Aggregator sessions. A minimal pseudonymous provider/subject security tombstone remains. Existing private backups are not immediately erased; local backup cleanup is an outstanding operator task. This does not delete your Google account.</p><label>Type DELETE MY AGGREGATOR ACCOUNT<input v-model="confirmation" class="field-input" autocomplete="off"></label><button class="control" :disabled="busy||confirmation!=='DELETE MY AGGREGATOR ACCOUNT'" @click="accountAction('delete-account')">Permanently delete Aggregator account</button></details></section></template><p role="alert">{{ error }}</p></MemberFrame></template>


<style scoped>.profile-initial{display:inline-grid;place-items:center;width:3rem;height:3rem;border:1px solid currentColor;border-radius:50%;margin-block:1rem;font-size:1.5rem}.profile-export{white-space:pre-wrap;overflow-wrap:anywhere;max-height:30rem;overflow:auto}details{margin-block:1rem}</style>



